#include <iostream>
#include <queue>
#include <cstring>
#include <climits>
#include <algorithm>
#include <chrono>
#include <random>
using namespace std;

using ll = long long;
using pii = pair<int, int>;

mt19937_64 rng(chrono::steady_clock::now().time_since_epoch().count());

const int MAXN = 12;
const int INF = 1000000009;
const int DR[4] = {0, 1, 0, -1};
const int DC[4] = {1, 0, -1, 0};

int n, t;
char grid1[MAXN][MAXN], grid2[MAXN][MAXN];
int dist[MAXN][MAXN];
bool visited[MAXN][MAXN];

struct Cell {
    int r, c;
    Cell() {}
    Cell(int r, int c) : r(r), c(c) {}
};

void bfs_search(int sr, int sc) {
    for (int i = 0; i < n; ++i) fill(dist[i], dist[i] + n, INF);
    memset(visited, 0, sizeof(visited));
    queue<Cell> q;
    visited[sr][sc] = true;
    dist[sr][sc] = 0;
    q.emplace(sr, sc);
    while (!q.empty()) {
        Cell cur = q.front(); q.pop();
        for (int i = 0; i < 4; ++i) {
            int nr = cur.r + DR[i], nc = cur.c + DC[i];
            if (nr >= 0 && nr < n && nc >= 0 && nc < n && !visited[nr][nc] && isdigit(grid1[nr][nc])) {
                visited[nr][nc] = true;
                dist[nr][nc] = dist[cur.r][cur.c] + 1;
                q.emplace(nr, nc);
            }
        }
    }
}

bool dp[72][12][12][12][12];
bool can_reach[12][12][12][12];

int edge[290][290];
int prev_node[290];
bool in_queue[290];

bool find_path() {
    memset(in_queue, 0, sizeof(in_queue));
    memset(prev_node, 0, sizeof(prev_node));
    queue<int> q;
    in_queue[0] = true;
    q.push(0);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        if (u == 2 * n * n + 1) return true;
        for (int v = 0; v <= 2 * n * n + 1; ++v) {
            if (edge[u][v] && !in_queue[v]) {
                in_queue[v] = true;
                prev_node[v] = u;
                q.push(v);
            }
        }
    }
    return false;
}

void run() {
    cin >> n >> t;
    for (int i = 0; i < n; ++i) cin >> grid1[i];
    for (int i = 0; i < n; ++i) cin >> grid2[i];
    int start_r, start_c;
    cin >> start_r >> start_c;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid1[i][j] == 'Z') {
                start_r = i; start_c = j;
            }
        }
    }
    bfs_search(start_r, start_c);
    memset(dp, 0, sizeof(dp));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (isdigit(grid1[i][j])) {
                dp[0][i][j][i][j] = true;
            }
        }
    }
    for (int step = 0; step < t; ++step) {
        for (int pr = 0; pr < n; ++pr) {
            for (int pc = 0; pc < n; ++pc) {
                for (int r = 0; r < n; ++r) {
                    for (int c = 0; c < n; ++c) {
                        if (!dp[step][pr][pc][r][c]) continue;
                        if (dist[r][c] <= step) continue;
                        for (int d = 0; d < 4; ++d) {
                            int nr = r + DR[d], nc = c + DC[d];
                            if (nr >= 0 && nr < n && nc >= 0 && nc < n && isdigit(grid1[nr][nc]) && dist[nr][nc] >= step + 1) {
                                dp[step + 1][pr][pc][nr][nc] = true;
                            }
                        }
                    }
                }
            }
        }
    }
    memset(can_reach, 0, sizeof(can_reach));
    for (int step = 0; step <= t; ++step) {
        for (int pr = 0; pr < n; ++pr) {
            for (int pc = 0; pc < n; ++pc) {
                for (int r = 0; r < n; ++r) {
                    for (int c = 0; c < n; ++c) {
                        if (dp[step][pr][pc][r][c]) {
                            can_reach[pr][pc][r][c] = true;
                        }
                    }
                }
            }
        }
    }
    memset(edge, 0, sizeof(edge));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (isdigit(grid1[i][j])) {
                edge[0][i * n + j + 1] = grid1[i][j] - '0';
            }
        }
    }
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (isdigit(grid2[i][j])) {
                edge[n * n + i * n + j + 1][2 * n * n + 1] = grid2[i][j] - '0';
            }
        }
    }
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (!isdigit(grid1[i][j])) continue;
            for (int k = 0; k < n; ++k) {
                for (int l = 0; l < n; ++l) {
                    if (!isdigit(grid1[k][l])) continue;
                    if (!can_reach[i][j][k][l]) continue;
                    edge[i * n + j + 1][n * n + k * n + l + 1] = INF;
                }
            }
        }
    }
    while (find_path()) {
        int flow = INF;
        for (int u = 2 * n * n + 1; u; u = prev_node[u]) {
            flow = min(flow, edge[prev_node[u]][u]);
        }
        for (int u = 2 * n * n + 1; u; u = prev_node[u]) {
            edge[prev_node[u]][u] -= flow;
            edge[u][prev_node[u]] += flow;
        }
    }
    int max_flow = 0;
    for (int i = 0; i <= 2 * n * n + 1; ++i) {
        max_flow += edge[i][0];
    }
    cout << max_flow << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    run();
    return 0;
}
